-- Parity test for Cognos report Emergency_Operations_Dashboard (cluster OPS_006, 1 runs/day)
-- Generated by SemLift 1.0.0; tolerance +/-0.5% on totals
WITH cognos AS (
    SELECT dt.FULL_DATE AS full_date, location.REGION AS region, outage_cause.CAUSE_CODE AS cause_code, SUM(outage_event.CUSTOMERS_AFFECTED) AS total_customers_affected, SUM(outage_event.DURATION_MINUTES) AS total_duration_minutes, SUM(outage_event.SAIDI_MINUTES) AS total_saidi_minutes, SUM(outage_event.SAIFI_COUNT) AS total_saifi_count
    FROM CORE.FCT_OUTAGE_EVENT outage_event
    JOIN CORE.DIM_DATE dt ON outage_event.DATE_KEY = dt.DATE_KEY
    JOIN CORE.DIM_LOCATION location ON outage_event.LOCATION_ID = location.LOCATION_ID
    JOIN CORE.DIM_OUTAGE_CAUSE outage_cause ON outage_event.CAUSE_CODE = outage_cause.CAUSE_CODE
    WHERE dt.FISCAL_YEAR = 2026
    GROUP BY 1, 2, 3
),
semantic AS (
    SELECT * FROM SEMANTIC_VIEW(
        SEM.SV_GRID_RELIABILITY
        DIMENSIONS dt.full_date, location.region, outage_cause.cause_code
        METRICS outage_event.total_customers_affected, outage_event.total_duration_minutes, outage_event.total_saidi_minutes, outage_event.total_saifi_count
    ) WHERE fiscal_year = 2026
)
SELECT
    (SELECT COUNT(*) FROM cognos) AS cognos_rows,
    (SELECT COUNT(*) FROM semantic) AS semantic_rows,
    SUM(c.total_customers_affected) AS cognos_total_customers_affected, SUM(s.total_customers_affected) AS semantic_total_customers_affected,
    IFF(ABS(COALESCE(SUM(s.total_customers_affected), 0) - COALESCE(SUM(c.total_customers_affected), 0)) <= 0.5 / 100 * ABS(NULLIF(SUM(c.total_customers_affected), 0)), 'PASS', 'FAIL') AS status_total_customers_affected,
    SUM(c.total_duration_minutes) AS cognos_total_duration_minutes, SUM(s.total_duration_minutes) AS semantic_total_duration_minutes,
    IFF(ABS(COALESCE(SUM(s.total_duration_minutes), 0) - COALESCE(SUM(c.total_duration_minutes), 0)) <= 0.5 / 100 * ABS(NULLIF(SUM(c.total_duration_minutes), 0)), 'PASS', 'FAIL') AS status_total_duration_minutes,
    SUM(c.total_saidi_minutes) AS cognos_total_saidi_minutes, SUM(s.total_saidi_minutes) AS semantic_total_saidi_minutes,
    IFF(ABS(COALESCE(SUM(s.total_saidi_minutes), 0) - COALESCE(SUM(c.total_saidi_minutes), 0)) <= 0.5 / 100 * ABS(NULLIF(SUM(c.total_saidi_minutes), 0)), 'PASS', 'FAIL') AS status_total_saidi_minutes,
    SUM(c.total_saifi_count) AS cognos_total_saifi_count, SUM(s.total_saifi_count) AS semantic_total_saifi_count,
    IFF(ABS(COALESCE(SUM(s.total_saifi_count), 0) - COALESCE(SUM(c.total_saifi_count), 0)) <= 0.5 / 100 * ABS(NULLIF(SUM(c.total_saifi_count), 0)), 'PASS', 'FAIL') AS status_total_saifi_count
FROM cognos c
FULL OUTER JOIN semantic s ON c.full_date IS NOT DISTINCT FROM s.full_date AND c.region IS NOT DISTINCT FROM s.region AND c.cause_code IS NOT DISTINCT FROM s.cause_code;
